import{_ as t,o,c as r,a2 as a}from"./chunks/framework.DtT7EKm8.js";const p=JSON.parse('{"title":"One Kotlin Multiplatform core for every platform","description":"","frontmatter":{"status":"accepted","date":"2026-10-24T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0002-one-kotlin-multiplatform-core.md","filePath":"docs/adr/0002-one-kotlin-multiplatform-core.md"}'),n={name:"docs/adr/0002-one-kotlin-multiplatform-core.md"};function l(i,e,s,d,c,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="one-kotlin-multiplatform-core-for-every-platform" tabindex="-1">One Kotlin Multiplatform core for every platform <a class="header-anchor" href="#one-kotlin-multiplatform-core-for-every-platform" aria-label="Permalink to &quot;One Kotlin Multiplatform core for every platform&quot;">​</a></h1><p>Android, iOS, the server and the website must run workouts identically. Domain types, the workout engine, workout type modules and stats live in shared Kotlin modules; Compose and SwiftUI only render and talk to hardware, and the server reuses the same modules on the JVM for validation. The website runs the engine compiled to JavaScript (decided 24 October 2026) rather than a TypeScript rewrite: a Kotlin/JS build step costs less than writing and testing the engine twice.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Modules the website needs use the <code>coachpoulpy.kmp-web-library</code> convention and must stay free of JVM-only or mobile-only dependencies.</li><li>iOS consumes everything through the <code>shared</code> umbrella framework.</li></ul>',4)])])}const f=t(n,[["render",l]]);export{p as __pageData,f as default};
